/** Every word used on a card above, deduplicated. */
export function curatedWords() {
  return [...new Set(QURAN_CARDS.flatMap((c) => c.words))];
}

/**
 * Curated words the corpus does not attest — which must always be empty.
 *
 * This is the guard that makes the whole feature trustworthy. A typo in a
 * harakah above produces a string that is not in the mushaf, and without this
 * check it would render perfectly and teach a child a word that does not
 * exist. The tests fail on any non-empty result, so the only words that can
 * reach a card are words the mining run found in the text.
 */
export function unattested() {
  return curatedWords().filter((w) => !attested(w));
}

/** Curated words with no English gloss — also expected to be empty. */
export function unglossed() {
  return curatedWords().filter((w) => !QURAN_GLOSS[w]);
}

/** The ayah a word was taken from, e.g. "2:29", or null if it is not mined. */
export function ayahOf(word) {
  return attested(word)?.ref ?? null;
}

/** How many times the Quran uses this word, for a teacher ordering a lesson. */
export function countOf(word) {
  return attested(word)?.count ?? 0;
}

/** The whole mined corpus, for a teacher looking for a word to add. */
export { QURAN_CORPUS };
